+const R: f64 = 4.0;
+const STEP: f64 = 2.0;
+
+fn region(loops: Vec<Vec<Point2>>) -> Region {
+    let loops = loops.into_iter().map(|l| Loop::new(l).unwrap_or_else(|e| panic!("loop: {e:?}"))).collect();
+    Region::new(loops).unwrap_or_else(|e| panic!("region: {e:?}"))
+}
